using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsMeshSnapshotOperations:RefCounted
{
    private readonly ModelMeshOperations _meshes=new();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    public Settings capture(Control editor,Resource actor,bool depositsOnly){string id=actor.Get("id").AsString();var physics=editor.Get("physics").AsGodotObject();var state=Get(physics.Get("display_states").AsGodotDictionary(),id,new Settings()).AsGodotDictionary();if(state.Count==0)return new Settings{["error"]="No evaluated physics state at this playhead."};var clip=editor.Get("model").AsGodotObject().Call("clip_for_actor_id",id).As<Resource>();var runtime=editor.Call("_runtime_for_clip",clip.Get("id")).As<Node3D>();var combined=new KiwiModelMesh();var materials=new Godot.Collections.Array<Material>();bool powder=false;var script=runtime?.GetScript().As<Script>();while(script!=null){if(script.ResourcePath=="res://scripts/actors/physics/powder/KiwiPowderRuntime.cs"){powder=true;break;}script=script.GetBaseScript();}if(powder&&runtime!=null){int maximum=0;var points=state["points"].AsVector3Array();var ids=state["powder_ids"].AsInt32Array();var phase=state["powder_phase"].AsByteArray();var radii=state["powder_radii"].AsFloat32Array();var identities=runtime.Get("identities").AsGodotDictionary();var geometry=runtime.Get("geometry").AsGodotArray();var converted=new Resource?[geometry.Count];for(int i=0;i<points.Length;i++){if(depositsOnly&&phase[i]!=1)continue;var identity=identities.TryGetValue(ids[i],out var value)?value.AsGodotDictionary():new Settings();if(identity.Count==0)continue;int variant=identity["variant"].AsInt32();var mesh=converted[variant]??= _meshes.from_mesh(geometry[variant].As<Mesh>());maximum+=mesh.Get("vertices").AsVector3Array().Length;if(maximum>150000)return new Settings{["error"]="Mesh conversion exceeds 150,000 vertices. Use fewer grains or lower geometry detail."};_meshes.append_mesh(combined,mesh,new Transform3D(identity["basis"].AsBasis().Scaled(Vector3.One*radii[i]),points[i]),0);}materials.Add(runtime.Get("batches").AsGodotArray()[0].As<MultiMeshInstance3D>().MaterialOverride!);}else{int totalVertices=0;var nodes=physics.Get("destruction").AsGodotObject().Get("nodes").AsGodotDictionary();foreach(var value in Get(nodes,id,new GArray()).AsGodotArray()){var node=value.As<MeshInstance3D>();if(!node.Visible||node.Mesh==null)continue;var mesh=_meshes.from_mesh(node.Mesh);totalVertices+=mesh.Get("vertices").AsVector3Array().Length;if(totalVertices>150000)return new Settings{["error"]="Mesh conversion exceeds 150,000 vertices. Use simpler damage geometry."};_meshes.append_mesh(combined,mesh,node.GlobalTransform,materials.Count);for(int surface=0;surface<node.Mesh.GetSurfaceCount();surface++)materials.Add(node.GetActiveMaterial(surface)!);}}if(combined.Get("faces").AsGodotArray().Count==0)return new Settings{["error"]="There is no compatible visible geometry to save at this time."};return new Settings{["error"]="",["mesh"]=_meshes.render_mesh(combined,materials),["editable"]=combined};}
    public Settings prompt_prepare(Node owner,RefCounted model,Resource actor,bool depositsOnly){foreach(var node in owner.GetTree().GetNodesInGroup("actor_timeline_editors"))if(node.Get("model").AsGodotObject()==model)return capture((Control)node,actor,depositsOnly);return new Settings{["missing"]=true};}
    public Settings prompt_finish(Settings result,Settings destination){if(Get(destination,"cancelled",true).AsBool())return new Settings{["done"]=true};string path=Get(destination,"path","").AsString();if(path.Length==0)return new Settings{["done"]=true};if(ResourceSaver.Save(result["mesh"].As<Resource>(),path)==Error.Ok){var filesystem=GD.Load<GDScript>("res://scripts/Globals/local_project_filesystem.gd");if(filesystem.Get("node").AsGodotObject()!=null)filesystem.Call("update_root_folder");return new Settings{["done"]=true};}return new Settings{["done"]=false,["error"]="The mesh could not be saved to the chosen location."};}
    public void show_error(Node owner,string error){if(!GodotObject.IsInstanceValid(owner))return;var dialog=new AcceptDialog{Title="Mesh snapshot",DialogText=error};owner.AddChild(dialog);dialog.Confirmed+=dialog.QueueFree;dialog.Canceled+=dialog.QueueFree;dialog.PopupCentered(new Vector2I(380,130));}
}
